#include <ch32v20x.h>
#include <debug.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    GPIO_TypeDef* port;
    uint16_t pin;
} GPIO_Pin_Map_t;

static const GPIO_Pin_Map_t col_pins[8] = {
    {GPIOB, GPIO_Pin_1},
    {GPIOA, GPIO_Pin_2},
    {GPIOA, GPIO_Pin_3},
    {GPIOA, GPIO_Pin_4},
    {GPIOA, GPIO_Pin_5},
    {GPIOA, GPIO_Pin_6},
    {GPIOA, GPIO_Pin_7},
    {GPIOB, GPIO_Pin_0}
};

// Rows (Sources, Push-Pull)
static const GPIO_Pin_Map_t row_pins[8] = {
    {GPIOA, GPIO_Pin_1},
    {GPIOA, GPIO_Pin_0},
    {GPIOB, GPIO_Pin_7},
    {GPIOB, GPIO_Pin_6},
    {GPIOB, GPIO_Pin_5},
    {GPIOB, GPIO_Pin_4},
    {GPIOB, GPIO_Pin_3},
    {GPIOA, GPIO_Pin_15}
};


void NMI_Handler(void) __attribute__((interrupt("WCH-Interrupt-fast")));
void HardFault_Handler(void) __attribute__((interrupt("WCH-Interrupt-fast")));

void matrix_init(void) {
    GPIO_InitTypeDef GPIO_InitStructure = {0};

    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_GPIOB | RCC_APB2Periph_AFIO, ENABLE);
    GPIO_PinRemapConfig(GPIO_Remap_SWJ_Disable, ENABLE);

    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_OD;
    for(uint8_t i = 0; i < 8; i++) {
        GPIO_InitStructure.GPIO_Pin = col_pins[i].pin;
        GPIO_Init(col_pins[i].port, &GPIO_InitStructure);
        GPIO_WriteBit(col_pins[i].port, col_pins[i].pin, Bit_SET);
    }

    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_Out_PP;
    for(uint8_t i = 0; i < 8; i++) {
        GPIO_InitStructure.GPIO_Pin = row_pins[i].pin;
        GPIO_Init(row_pins[i].port, &GPIO_InitStructure);
        GPIO_WriteBit(row_pins[i].port, row_pins[i].pin, Bit_RESET);
    }
}

